def domainRealEquiv (f : U ≃ₗ[Hᵐᵒᵖ] W) : U ≃ₗ[ℝ] RestrictScalars ℝ Hᵐᵒᵖ W :=
  { f.toAddEquiv with
    map_smul' := by
      intro r x
      change f (r • x) = (algebraMap ℝ Hᵐᵒᵖ r) • f x
      rw [← algebraMap_smul Hᵐᵒᵖ r x, f.map_smul] }

